#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: Kora release signing. Everything Apple and GitHub need before
# `pnpm release` can ship a signed, notarized, self-updating build:
#   GitHub Actions secrets on the source repository (KORA_SOURCE_REPO; read by a release workflow, if you use one)
#     MACOS_CERTIFICATE, MACOS_CERTIFICATE_PASSWORD   Developer ID Application cert + key (.p12)
#     APPLE_API_KEY, APPLE_API_KEY_ID, APPLE_API_ISSUER   App Store Connect API key (notarization)
#     RELEASES_TOKEN                                  publishes releases to agilkatakam/kora
#   plus a notarytool keychain profile "kora-notary" so scripts/release-app.sh also works on this Mac.
# Non-secret answers are remembered in .env.release (gitignored) for re-runs; secrets are never written to disk.
# Run from the repo root: bash scripts/release-setup.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
ENV_FILE=".env.release"
export GH_REPO="${KORA_SOURCE_REPO:-Koragraph/Kora}"   # where CI secrets go
PUBLIC_REPO="${KORA_PUBLIC_REPO:-agilkatakam/kora}"   # where signed builds are published
NOTARY_PROFILE="kora-notary"

banner "Kora release signing (Apple Developer ID + notarization + GitHub)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Apple Developer Program"
if [[ -n "$(_existing APPLE_TEAM_ID || true)" ]]; then
  say "Team ID on file from an earlier run: ${BOLD}$(_existing APPLE_TEAM_ID)${RESET}."
else
  say "Notarized apps need a paid Apple Developer membership (\$99/year)."
  say "Already a member? Just press Enter at the next prompt."
  open_url "https://developer.apple.com/programs/enroll/"
  step "Sign in with your Apple ID and start the enrollment."
  step "Individual: fastest (usually approved within 48 hours); users see your own legal name as the developer."
  step "Organization: users see the company name, but it needs a registered company and a D-U-N-S number"
  step "(free, can take 1–2 weeks). You can start as an individual and move to an organization later."
  step "Pay, then wait for Apple's \"Welcome to the Apple Developer Program\" email."
  pause "Enrolled and approved? Press Enter."
  open_url "https://developer.apple.com/account#MembershipDetailsCard"
  step "On the Account page, find Membership details → Team ID (10 letters/digits)."
fi
ask APPLE_TEAM_ID "Team ID:"
write_env APPLE_TEAM_ID "$APPLE_TEAM_ID"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Developer ID Application certificate"
say "This certificate is what makes macOS trust Kora downloads. Only the account holder can create one."
find_identity() {
  security find-identity -v -p codesigning 2>/dev/null | sed -n 's/.*"\(Developer ID Application: .*\)"$/\1/p' | head -1
}
SIGN_IDENTITY="$(find_identity)"
if [[ -n "$SIGN_IDENTITY" ]]; then
  say "Found it in your keychain already: ${BOLD}$SIGN_IDENTITY${RESET}"
else
  step "Open Xcode → Settings… (⌘,) → Accounts."
  step "You need the Apple ID that owns team $APPLE_TEAM_ID (your paid team, not one labelled \"Personal Team\")."
  step "Not listed? Click + (bottom left) → Apple ID → sign in. Then select that account and team."
  step "Click Manage Certificates… → the + menu (bottom left) → Developer ID Application → Done."
  note "Developer ID Application greyed out? Only the team's account holder can create it."
  note "No Xcode? developer.apple.com → Certificates → + → Developer ID Application, upload a CSR from"
  note "Keychain Access → Certificate Assistant → Request a Certificate From a Certificate Authority, then"
  note "double-click the downloaded .cer to install it."
  while true; do
    pause "Created it? Press Enter (nothing to type here) and I'll look for it."
    SIGN_IDENTITY="$(find_identity)"
    [[ -n "$SIGN_IDENTITY" ]] && break
    warn "no Developer ID Application certificate in your keychain yet"
    confirm "Look again?" || break
  done
fi
if [[ -n "$SIGN_IDENTITY" ]]; then
  say "${GREEN}✓${RESET} $SIGN_IDENTITY"
  write_env KORA_SIGN_IDENTITY "$SIGN_IDENTITY"
  case "$SIGN_IDENTITY" in
    *"($APPLE_TEAM_ID)"*) ;;
    *) warn "this certificate's team isn't $APPLE_TEAM_ID: check you picked the right team" ;;
  esac
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Export the certificate for GitHub Actions"
if [[ -z "$SIGN_IDENTITY" ]]; then
  warn "skipped: there's no Developer ID certificate to export yet (stage 2)"
  SKIPPED+=("Developer ID certificate + MACOS_CERTIFICATE / MACOS_CERTIFICATE_PASSWORD (create it, then re-run)")
  pause "Press Enter to go on to the next stage."
else
  say "CI signs the app on a clean Mac, so it needs a copy of the certificate and its private key (.p12)."
  step "Open Keychain Access (Spotlight → Keychain Access) → login keychain → My Certificates tab."
  step "Right-click \"$SIGN_IDENTITY\" → Export…"
  step "Format: Personal Information Exchange (.p12). Save it as ~/Desktop/kora-developer-id.p12."
  step "Make up a new export password for the file. You'll type it here in a moment, at a hidden prompt."
  step "macOS then asks for your Mac login password to allow the export: type that one in macOS's dialog only."
  pause "Exported? Press Enter (nothing to type here)."
  P12_PATH=""
  while true; do
    ask P12_FILE "Path to the .p12 [Enter = ~/Desktop/kora-developer-id.p12]:"
    P12_PATH="${P12_FILE:-$HOME/Desktop/kora-developer-id.p12}"
    P12_PATH="${P12_PATH/#\~/$HOME}"
    ask_secret P12_PASSWORD "The .p12 export password (hidden as you type):"
    if [[ ! -f "$P12_PATH" ]]; then
      warn "no file at $P12_PATH"
    # The password goes through the environment, not argv (`pass:` would show it to every user in `ps`).
    elif ! SUBJECT="$(KORA_P12_PASSWORD="$P12_PASSWORD" /usr/bin/openssl pkcs12 -in "$P12_PATH" -nokeys \
      -passin env:KORA_P12_PASSWORD 2>/dev/null |
      /usr/bin/openssl x509 -noout -subject 2>/dev/null)" || [[ -z "$SUBJECT" ]]; then
      warn "that password doesn't open $P12_PATH (it's the password you chose when exporting, not your Mac's)"
    elif [[ "$SUBJECT" != *"Developer ID Application"* ]]; then
      warn "the password is right, but this file holds a different certificate:"
      warn "  ${SUBJECT#subject=}"
      warn "export \"$SIGN_IDENTITY\" instead (Keychain Access → My Certificates)"
    else
      say "${GREEN}✓${RESET} ${SUBJECT#subject=}"
      break
    fi
    confirm "Try again?" || { P12_PATH=""; break; }
  done
  if [[ -n "$P12_PATH" ]]; then
    write_env P12_FILE "$P12_PATH"
    set_secret MACOS_CERTIFICATE "$(base64 -i "$P12_PATH")"
    set_secret MACOS_CERTIFICATE_PASSWORD "$P12_PASSWORD"
    note "Keep a copy of the .p12 + password in your password manager: it's your only backup of the private key."
    if confirm "Delete $P12_PATH from this Mac now (after you've backed it up)?"; then
      rm -f "$P12_PATH" && say "${GREEN}✓${RESET} deleted"
    fi
  else
    SKIPPED+=("MACOS_CERTIFICATE + MACOS_CERTIFICATE_PASSWORD (re-run this wizard)")
  fi
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "App Store Connect API key (notarization)"
say "Apple checks every release for malware before macOS will open it (notarization). This key lets the"
say "release script submit builds without your Apple ID password."
open_url "https://appstoreconnect.apple.com/access/integrations/api"
step "Integrations → App Store Connect API → Team Keys. First time: click Request Access and accept."
step "Click + (Generate API Key). Name: Kora notarization. Access: Developer. Generate."
step "Click Download next to the new key: AuthKey_XXXXXXXXXX.p8 (Apple lets you download it only ONCE)."
step "Copy the Key ID from the key's row, and the Issuer ID shown above the table."
pause "Downloaded? Press Enter."
P8_GUESS="$(ls -t "$HOME"/Downloads/AuthKey_*.p8 2>/dev/null | head -1 || true)"
[[ -n "$P8_GUESS" ]] && note "found $P8_GUESS"
ask P8_FILE "Path to the .p8 file [${P8_GUESS:-~/Downloads/AuthKey_….p8}]:"
P8_PATH="${P8_FILE:-$P8_GUESS}"
P8_PATH="${P8_PATH/#\~/$HOME}"
ask APPLE_API_KEY_ID "Key ID:"
ask APPLE_API_ISSUER "Issuer ID:"
if [[ -f "$P8_PATH" ]] && grep -q "BEGIN PRIVATE KEY" "$P8_PATH"; then
  write_env P8_FILE "$P8_PATH"
  write_env APPLE_API_KEY_ID "$APPLE_API_KEY_ID"
  write_env APPLE_API_ISSUER "$APPLE_API_ISSUER"
  set_secret APPLE_API_KEY "$(cat "$P8_PATH")"
  set_secret APPLE_API_KEY_ID "$APPLE_API_KEY_ID"
  set_secret APPLE_API_ISSUER "$APPLE_API_ISSUER"
  say "Saving the same key on this Mac (keychain profile \"$NOTARY_PROFILE\") for local releases…"
  if xcrun notarytool store-credentials "$NOTARY_PROFILE" --key "$P8_PATH" --key-id "$APPLE_API_KEY_ID" \
    --issuer "$APPLE_API_ISSUER" >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} Apple accepted the key; stored as \"$NOTARY_PROFILE\""
  else
    SKIPPED+=("notarytool profile: xcrun notarytool store-credentials $NOTARY_PROFILE --key <p8> --key-id <id> --issuer <issuer>")
    warn "Apple didn't accept that key (check the Key ID / Issuer ID), or the network is down"
  fi
  note "Keep the .p8 in your password manager too, then you can delete it from Downloads."
else
  SKIPPED+=("APPLE_API_KEY / APPLE_API_KEY_ID / APPLE_API_ISSUER (re-run this wizard)")
  warn "no .p8 private key at ${P8_PATH:-that path}"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub token for publishing releases"
say "CI runs in the private repo and publishes to the public one ($PUBLIC_REPO), so it needs a"
say "token that can write releases there, and nowhere else."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: kora releases. Expiration: the longest offered (put a renewal reminder in your calendar)."
step "Repository access: Only select repositories → $PUBLIC_REPO."
step "Permissions → Repository permissions → Contents: Read and write. (Metadata: read is added for you.)"
step "Generate token, then copy it (starts with github_pat_)."
ask_secret RELEASES_TOKEN "Paste the token:"
if [[ -n "$RELEASES_TOKEN" ]]; then
  # A real write: a draft release (never public), deleted at once. (Reading the repo's `permissions` reports the
  # token OWNER's role, which passes even when the token itself lacks Contents: write.)
  DRAFT_ID="$(GH_TOKEN="$RELEASES_TOKEN" gh api -X POST "repos/$PUBLIC_REPO/releases" -f tag_name="token-check-$$" \
    -f name="token check (deleted at once)" -F draft=true --jq .id 2>/dev/null || true)"
  if [[ -n "$DRAFT_ID" ]]; then
    GH_TOKEN="$RELEASES_TOKEN" gh api -X DELETE "repos/$PUBLIC_REPO/releases/$DRAFT_ID" >/dev/null 2>&1 || true
    say "${GREEN}✓${RESET} the token can publish releases to $PUBLIC_REPO"
  else
    warn "this token can't create releases on $PUBLIC_REPO: edit it (github.com/settings/personal-access-tokens →"
    warn "kora releases → Edit) and set Repository permissions → Contents to Read and write. The token stays the same."
  fi
  set_secret RELEASES_TOKEN "$RELEASES_TOKEN"
else
  SKIPPED+=("RELEASES_TOKEN (re-run this wizard)")
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Check everything"
say "GitHub secrets on $GH_REPO:"
gh secret list 2>/dev/null | sed 's/^/    /' || warn "couldn't list secrets (gh not logged in?)"
say "Signing identity on this Mac: ${SIGN_IDENTITY:-none}"
if xcrun notarytool history --keychain-profile "$NOTARY_PROFILE" >/dev/null 2>&1; then
  say "Notarization profile \"$NOTARY_PROFILE\": ${GREEN}works${RESET}"
else
  warn "notarization profile \"$NOTARY_PROFILE\" doesn't answer yet"
fi
say ""
say "A signed + notarized test build on GitHub (not published) proves the whole chain:"
say "about 10–20 minutes of macOS build time."
if confirm "Start that test build now?"; then
  if gh workflow run release.yml -f unsigned=false >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} started: https://github.com/$GH_REPO/actions/workflows/release.yml"
  else
    warn "couldn't start it; run it from GitHub: Actions → Release → Run workflow (unsigned: off)"
  fi
fi
say ""
say "To ship: on a clean main, ${BOLD}pnpm release patch${RESET} (see docs/RELEASING.md)."
pause "Press Enter to finish."

finish
